import { assistantMarkup, mountAssistant } from './ai-assistant/loan-assistant.js';

import { LiveApi, ApiError } from './api.js';
import { config, terminalStates } from './config.js';
import { formatMoney, withApplicationStatuses, withOfferedAmounts } from './presentation.js';
import { states, citySuggestions } from './locations.js';
const $=s=>document.querySelector(s);
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=formatMoney;
const offered=r=>r.amountUnavailable?'Unavailable':money(r.offeredAmount);
const amountRows=rows=>withOfferedAmounts(rows,ids=>live.amounts(ids));
const human=value=>String(value||'').toLowerCase().replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const date=value=>value?new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'\u2014';
const short=value=>value?`${String(value).slice(0,8)}\u2026`: '\u2014';
const uid=()=>crypto.randomUUID();
const validId=value=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const icons={
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M8 13h8M8 17h5"/>',
  bank:'<path d="m3 9 9-6 9 6M4 10h16M3 21h18M6 11v7M12 11v7M18 11v7"/>',
  offer:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 10h18M7 15h4M8 2v5M16 2v5"/>',
  chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z"/><path d="M7 11h10M7 15h6"/>',
  chart:'<path d="M4 3v17h17M8 15l4-5 4 3 5-8"/>',
  shield:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z"/><path d="m8 12 3 3 5-6"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',
  settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3 3-1 3 1 1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3-3 1Z"/><circle cx="12" cy="12" r="3"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
  refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',
  check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
  logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M14 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>',
};
const icon=name=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const badge=status=>`<span class="pill ${['OFFER_ACCEPTED','ACTIVE','ACKNOWLEDGED','VERIFIED','OK'].includes(status)?'green':['ACTION_REQUIRED','ACTION_REQUIRED','PENDING','QUEUED','RETRY_PENDING','MANUAL_REVIEW'].includes(status)?'amber':['REJECTED','CANCELLED','FAILED','CHECK_FAILED'].includes(status)?'red':['EXPIRED','OFFER_EXPIRED','WITHDRAWN'].includes(status)?'gray':''}"><i class="dot"></i>${e(human(status||'Pending'))}</span>`;
const button=(label,action,cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const hint=(message,type='')=>`<div class="notice ${type}">${icon('info')}<div>${message}</div></div>`;
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="${name}">${e(label)}</label><input id="${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;
const amountField=(label,name,value='',extra='')=>field(label,name,value,'number',`${extra} list="${name}-options"`)+`<datalist id="${name}-options">${[50000,100000,200000,300000,500000,750000,1000000].map(v=>`<option value="${v}">${money(v)}</option>`).join('')}</datalist>`;
const tenureField=()=>`<div class="field"><label for="tenureMonths">Tenure in months</label><select id="tenureMonths" name="tenureMonths" required><option value="">Choose tenure</option>${[3,6,9,12,18,24,36,48,60,72,84,96,108,120].map(v=>`<option value="${v}">${v} months</option>`).join('')}<option value="custom">Other tenure</option></select></div><div class="field" hidden><label for="customTenureMonths">Other tenure in months</label><input id="customTenureMonths" name="customTenureMonths" type="number" min="1" max="120" step="1" disabled><small>Enter between 1 and 120 months.</small></div>`;
const cityOptions=state=>citySuggestions(state).map(city=>`<option value="${e(city)}"></option>`).join('');
const item=(label,value,wide=false)=>`<div class="data-item ${wide?'wide':''}"><dt>${e(label)}</dt><dd>${e(value??'\u2014')}</dd></div>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">${icon('file')}</div><h3>${e(title)}</h3><p>${e(text)}</p>${action}</div>`;

let portal={name:'CredFlow',role:''},lenderNames={},modalHandler=null,toastTimer,reviewRow=null;
const state={session:null,role:'',route:'overview',id:'',tab:'overview',rows:[],total:0,page:0,workflow:null,detail:null,timeline:null,offers:[],questions:[],consentInfo:null,eligibility:null,auditEvents:[],corrections:[],rules:[],services:[],loanRequests:[],sellers:[],marketplaces:[],lenders:[],accountProfile:null,profile:null,loading:false,error:null,epoch:0,lastUpdated:null};
const consentDrafts=new Map();
const live=new LiveApi({onUnauthorized:()=>clearSessionState('Your session expired or changed. Refresh or sign in again.')});
const api=()=>live;
const navs={MARKETPLACE:[['overview','Overview'],['applications','Applications'],['requests','Seller loan requests'],['sellers','Registered sellers'],['account-profile','My profile']],SELLER:[['overview','Overview'],['applications','My applications'],['requests','My loan requests'],['profile','My business profile']],LENDER_OFFICER:[['overview','Overview'],['submissions','Assigned applications'],['rules','Lender rules'],['account-profile','My profile']],ADMIN:[['overview','Overview'],['applications','Applications and audit'],['marketplaces','Marketplaces'],['lenders','Lenders / banks'],['routing','Routing priorities'],['accounts','User accounts'],['account-profile','My profile'],['services','Service status']]};
function go(route){if(location.hash===`#/${route}`)load();else location.hash=`#/${route}`;}
function routeParts(){const [route='overview',id='',tab='overview']=location.hash.replace(/^#\/?/,'').split('/');return {route:route||'overview',id,tab};}
function authorisedRoute(){return state.route==='application'||(navs[state.role]||[]).some(([r])=>r===state.route);}
async function logout(message='Signed out.'){try{await live.endSession();clearSessionState(message);}catch(error){toast(error.message||'Sign out could not be confirmed. Please try again.');}}
function clearSessionState(message='Signed out.') {consentDrafts.clear();live.clear();state.session=null;state.rows=[];state.detail=null;state.workflow=null;state.timeline=null;state.error=null;state.loading=false;state.epoch++;closeModal();shell();toast(message);}
function workspaceName(){return state.session&&state.role==='LENDER_OFFICER'?(lenderNames[state.session.lenderId]||portal.name):portal.name;}
function shell(){
 document.title=`CredFlow - ${workspaceName()}`;
 if(!state.session){$('#app').innerHTML=`<main id="main" class="auth-page"><section class="auth-card card"><a class="brand" href="#/overview"><img src="assets/favicon.svg" alt=""><span>cred<span>flow</span></span></a><p class="eyebrow section-space">${e(portal.name)} portal</p><h1 class="section-space">Welcome to CredFlow</h1><p class="muted section-space">Sign in to access your ${e(portal.name.toLowerCase())} workspace.</p><div class="section-space">${button('Sign in','login','primary')}${portal.role==='SELLER'?button('Register as a seller','register'):''}</div></section></main>`;return;}
 const links=navs[state.role]||[];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="icon-btn mobile-close" data-action="menu" aria-label="Close navigation">${icon('close')}</button><a class="brand" href="#/overview"><img src="assets/favicon.svg" alt=""><span>cred<span>flow</span></span></a><div class="workspace eyebrow">${e(workspaceName())} portal</div><nav class="nav" aria-label="Main navigation">${links.map(([r,label])=>`<a href="#/${r}" class="${state.route===r?'active':''}">${icon(r==='profile'?'shield':r==='accounts'?'grid':'file')}<span>${e(label)}</span></a>`).join('')}</nav><div class="sidebar-bottom"><p class="muted small">${e(state.session.username)}</p><div class="section-space">${button('Sign out','logout','ghost small')}</div></div></aside><div class="content"><header class="topbar"><div class="breadcrumb"><button class="icon-btn menu-btn" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><strong>${e(workspaceName())} workspace</strong></div><div class="topbar-actions"><span class="muted small session-name">${e(state.session.username)}</span>${button(`${icon('refresh')}<span>Refresh</span>`,'refresh','ghost small',`aria-label="Refresh current page" ${state.loading?'disabled':''}`)}</div></header><main id="main" class="page">${page()}</main></div></div>`;
}
function page(){
 if(!authorisedRoute())return empty('Page unavailable','This feature is not part of your role.');
 if(state.loading)return '<div class="loading"><div class="spinner"></div>Loading your records-</div>';
 if(state.error)return heading('Unable to load records','Use Refresh at the top to retrieve the current database records.')+errorHtml(state.error);
 if(state.route==='application')return detailView();
 if(state.route==='requests')return loanRequestsView();
 if(state.route==='profile')return profileView();
 if(state.route==='sellers')return sellersView();
 if(state.route==='accounts')return accountsView();
 if(state.route==='marketplaces')return marketplacesView();
 if(state.route==='lenders')return lendersView();
 if(state.route==='rules')return rulesView();
 if(state.route==='routing')return routingView();
 if(state.route==='account-profile')return accountProfileView();
 if(state.route==='services')return heading('Service status','Availability of the connected services.')+`<div class="connection-grid">${state.services.map(s=>`<section class="card card-body"><h3>${e(s.name)}</h3>${badge(s.status)}</section>`).join('')}</div>`;
 if(state.route==='overview'){
 const count=s=>state.rows.filter(r=>s.includes(r.workflow?.status||r.status)).length;
 return heading(`${workspaceName()} overview`,'Your authorised records, updated from the services.',state.role==='SELLER'?button('Apply for loan','apply-loan','primary'):'')+`<div class="stats">${[['Total records',state.total],['Awaiting consent',count(['DRAFT'])],['With lenders',count(['UNDER_REVIEW','SUBMITTING'])],['Offers available',count(['APPROVED'])]].map(([label,n])=>`<section class="stat"><p>${e(label)}</p><div class="stat-number">${n}</div></section>`).join('')}</div><p class="muted small section-space">Status counts reflect this page of records.</p>`+recordsTable();
 }
 return heading(state.role==='LENDER_OFFICER'?'Assigned applications':'Applications','Open a record to see its current status and available actions.',state.role==='SELLER'?button('Apply for loan','apply-loan','primary'):'')+recordsTable();
}
function pagination(){return `<div class="form-actions">${button('Previous','previous','',state.page===0?'disabled':'')}<span class="muted small">Page ${state.page+1} - ${state.total} records</span>${button('Next','next','',(state.page+1)*config.pageSize>=state.total?'disabled':'')}</div>`;}
function recordsTable(){
 if(!state.rows.length)return `<section class="card">${empty('No applications yet','Your database has no application records available to this account.')}</section>`;
 return `<section class="card"><div class="record-cards">${state.rows.map(r=>`<article class="record-card"><strong>${e(r.businessProfile?.businessName||r.registeredBusinessName||'\u2014')}</strong><span class="mono">${e(r.applicationReference||short(r.applicationId))}</span><span>Amount requested: ${money(r.requestedAmount)}</span><span>Amount offered: ${offered(r)}</span>${badge(r.workflow?.status||r.status)}${r.submissionId&&state.role==='LENDER_OFFICER'?button('Review','review','small',`data-id="${e(r.submissionId)}"`):`<a class="button small" href="#/application/${e(r.applicationId)}">Open</a>`}</article>`).join('')}</div><div class="table-wrap record-table"><table><thead><tr><th>Business</th><th>Reference</th><th>Amount requested</th><th>Amount offered</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.rows.map(r=>`<tr><td>${e(r.businessProfile?.businessName||r.registeredBusinessName||'-')}</td><td class="mono">${e(r.applicationReference||short(r.applicationId))}</td><td>${money(r.requestedAmount)}</td><td>${offered(r)}</td><td>${badge(r.workflow?.status||r.status)}</td><td>${r.submissionId&&state.role==='LENDER_OFFICER'?button('Review','review','small',`data-id="${e(r.submissionId)}"`):`<a class="button small" href="#/application/${e(r.applicationId)}">Open</a>`}</td></tr>`).join('')}</tbody></table></div>${pagination()}</section>`;
}
function profileView(){const r=state.profile;return heading('My business profile','Your current registration and contact details.',r?.sellerId?button('Edit contact details','edit-seller-profile','primary'):'')+`<section class="card card-body">${r&&r.sellerId?`<dl class="data-grid">${[['Full name',r.fullName],['Email',r.emailAddress],['Mobile',r.phone],['Business',r.businessName],['Business start date',r.businessStartDate],['Address',r.address],['City',r.city],['State',r.state],['Postal code',r.postalCode],['Marketplace seller reference',r.marketplaceSellerId]].map(([k,v])=>item(k,v)).join('')}</dl>`:empty('No registration profile','This account has no seller registration profile stored in the database.')}</section>`;}
function sellersView(){return heading('Registered sellers','Sellers registered with your marketplace.')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Seller</th><th>Business</th><th>Contact</th><th>Reference</th><th>Action</th></tr></thead><tbody>${state.sellers.map(r=>`<tr><td>${e(r.fullName)}</td><td>${e(r.businessName)}</td><td>${e(r.emailAddress)}<br>${e(r.phone)}</td><td>${e(r.marketplaceSellerId)}</td><td>${button('Business history','business-history','small',`data-id="${e(r.sellerId)}"`)}</td></tr>`).join('')||'<tr><td colspan="5">No sellers have registered with this marketplace.</td></tr>'}</tbody></table></div>${pagination()}</section>`;}
function rulesView(){return heading('Lender rules','Manage eligibility rules for your lender only. Each saved change creates a new version.')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Product / lender</th><th>Version</th><th>Loan amount range</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.rules.map(r=>`<tr><td>${e(r.productName)}<br><span class="muted small">${e(lenderNames[r.lenderId]||r.lenderId)}</span></td><td>${e(r.version)}</td><td>${money(r.minAmount)} - ${money(r.maxAmount)}</td><td>${badge(r.active?'ACTIVE':'INACTIVE')}</td><td><div class="row-actions">${button('Edit rules','edit-rules','small',`data-id="${e(r.productId)}"`)}${button('History','rule-history','small',`data-id="${e(r.productId)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="5">No lender products configured.</td></tr>'}</tbody></table></div><div class="card-body"><p class="muted small">Changes apply to subsequent evaluations; previous assessments keep their recorded rule version.</p></div></section>`;}
async function rulesForm(id){
 if(state.role!=='LENDER_OFFICER')throw Error('Lender access required.');const fresh=await live.request('eligibility','/api/v1/lender-products'),r=fresh.items.find(v=>v.productId===id);if(!r)throw Error('Product not found. Refresh the page.');
 modal('Edit lender rules',`<p class="modal-intro">${e(r.productName)} - current version ${e(r.version)}. Saving creates a new version.</p><form><div class="form-grid">${field('Product name','productName',r.productName,'text','required maxlength="100"')}${field('Minimum business age (months)','minAgeMonths',r.minAgeMonths,'number','required min="0" max="1200" step="1"')}${field('Minimum average monthly net sales','minAverageNet',r.minAverageNet,'number','required min="0" max="999999999999.99" step="0.01"')}${field('Maximum return rate (%)','maxReturnPercent',r.maxReturnPercent,'number','required min="0" max="100" step="0.0001"')}${field('Minimum loan amount','minAmount',r.minAmount,'number','required min="0.01" max="999999999999.99" step="0.01"')}${field('Maximum loan amount','maxAmount',r.maxAmount,'number','required min="0.01" max="999999999999.99" step="0.01"')}${field('Net-sales multiplier','salesMultiplier',r.salesMultiplier,'number','required min="0.0001" max="9999999" step="0.0001"')}<div class="field"><label for="active">Product status</label><select id="active" name="active"><option value="true" ${r.active?'selected':''}>Active</option><option value="false" ${!r.active?'selected':''}>Inactive</option></select></div></div><fieldset class="section-space"><legend>Allowed loan purposes</legend>${['WORKING_CAPITAL','PURCHASE_INVENTORY','BUSINESS_EXPANSION'].map(v=>`<label class="checkbox"><input type="checkbox" name="purposes" value="${v}" ${r.purposes.includes(v)?'checked':''}>${e(human(v))}</label>`).join('')}</fieldset><div class="field"><label for="minCreditScoreBand">Minimum credit-score band</label><select id="minCreditScoreBand" name="minCreditScoreBand" required>${['POOR','FAIR','GOOD','EXCELLENT'].map(v=>`<option value="${v}" ${r.minCreditScoreBand===v?'selected':''}>${human(v)}</option>`).join('')}</select></div>${field('Maximum repayment share of disposable income (%)','maxRepaymentPercent',r.maxRepaymentPercent,'number','required min="0.01" max="100" step="0.01"')}${field('Assessment annual interest rate (%)','assessmentAprPercent',r.assessmentAprPercent,'number','required min="0" max="100" step="0.01"')}${field('Reason for this change','reason','','text','required maxlength="500"')}<div id="form-error" class="error-inline" role="alert"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="button primary">Save new rule version</button></div></form>`,async form=>{const fd=new FormData(form),data=Object.fromEntries(fd);data.purposes=fd.getAll('purposes');if(!data.purposes.length)throw Error('Choose at least one purpose.');data.expectedVersion=Number(r.version);data.minAgeMonths=Number(data.minAgeMonths);data.active=data.active==='true';await live.request('eligibility',`/api/v1/lender-products/${id}/rules`,data,'PUT');closeModal();await load();toast('New lender-rule version saved.');});
}
function routingView(){
 if(state.role!=='ADMIN')return empty('Section unavailable','Administrator access required.');
 return heading('Routing priorities','Set the order used when multiple lender products are eligible. Lower numbers are selected first.')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Lender / product</th><th>Routing priority</th><th>Version</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.rules.map(r=>`<tr><td>${e(lenderNames[r.lenderId]||r.lenderId)}<br><span class="muted small">${e(r.productName)}</span></td><td>${e(r.routingPriority)}</td><td>${e(r.version)}</td><td>${badge(r.active?'ACTIVE':'INACTIVE')}</td><td>${button('Set priority','edit-routing','small',`data-id="${e(r.productId)}"`)}</td></tr>`).join('')||'<tr><td colspan="5">No lender products configured.</td></tr>'}</tbody></table></div><div class="card-body"><p class="muted small">Priority changes apply to subsequent assessments. Existing applications keep their recorded lender selection. Eligibility rules remain controlled by the respective lender.</p></div></section>`;
}
function routingForm(id){
 if(state.role!=='ADMIN')throw Error('Administrator access required.');
 const r=state.rules.find(v=>v.productId===id);if(!r)throw Error('Product not found. Refresh the page.');
 modal('Set routing priority',`<p class="modal-intro">${e(lenderNames[r.lenderId]||r.lenderId)} - ${e(r.productName)}</p><p>Moving a lender shifts every lender between its old and new positions by one place. Your reason is recorded for every affected change.</p><form>${field('Routing priority (lower first)','routingPriority',r.routingPriority,'number',`required min="1" max="${state.rules.length}" step="1"`)}${field('Reason for this change','reason','','text','required maxlength="450"')}<div id="form-error" class="error-inline" role="alert"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="button primary">Save priority</button></div></form>`,async form=>{
  const data=Object.fromEntries(new FormData(form));data.routingPriority=Number(data.routingPriority);data.expectedVersion=r.version;
  await live.request('eligibility',`/api/v1/admin/routing-priorities/${id}`,data,'PUT');closeModal();await load();toast('Routing priority saved.');
 });
}
async function ruleHistory(id){if(state.role!=='LENDER_OFFICER')throw Error('Lender access required.');const history=await live.request('eligibility',`/api/v1/lender-products/${id}/rules/history`);modal('Lender rule history',`<div class="stack">${history.items.map(r=>`<section class="notice"><div><strong>Version ${e(r.version)} - ${e(r.productName)}</strong><p>${money(r.minAmount)} - ${money(r.maxAmount)} | ${r.active?'Active':'Inactive'}</p><p>Minimum age ${e(r.minAgeMonths)} months; net sales ${money(r.minAverageNet)}; returns at most ${e(r.maxReturnPercent)}%; multiplier ${e(r.salesMultiplier)}.</p><p>${e(r.purposes.map(human).join(', '))}</p><p>Minimum credit band: ${e(human(r.minCreditScoreBand))}; maximum disposable-income repayment share: ${e(r.maxRepaymentPercent)}%; assessment APR: ${e(r.assessmentAprPercent)}%.</p><p>${e(r.reason||'Initial configured rules')} ${r.changedAt?' | '+e(r.changedAt):''}</p>${r.actorId?`<p class="muted small">Changed by ${e(r.actorId)}</p>`:''}</div></section>`).join('')}</div><div class="form-actions">${button('Close','close')}</div>`);}
function correctionBusy(){return state.workflow?.revisionPending||state.corrections.some(r=>['PENDING','PROCESSING','RETRY_PENDING'].includes(r.status)||(r.status==='APPLIED'&&r.newRevision>state.workflow?.applicationRevision));}
function correctionsView(){return `<section class="card card-body"><h2>Application corrections</h2><p class="section-space">Corrections keep the previous application snapshot and start fresh checks for the new revision.</p>${state.role==='SELLER'&&state.workflow?.status==='ACTION_REQUIRED'&&!state.workflow?.submissionId?`<div class="section-space">${button('Correct application','correct-application','primary',correctionBusy()?'disabled':'')}</div>`:''}${state.corrections.length?`<div class="table-wrap section-space"><table><thead><tr><th>Revision</th><th>Status</th><th>Requested</th><th>Details</th></tr></thead><tbody>${state.corrections.map(r=>`<tr><td>${e(r.previousRevision)} to ${e(r.newRevision)}</td><td>${badge(r.status)}</td><td>${e(date(r.createdAt))}</td><td>${e(r.errorCode?human(r.errorCode):r.status==='APPLIED'?'Saved; workflow checks apply to the new revision.':'Waiting for workflow authorisation and processing.')}</td></tr>`).join('')}</tbody></table></div>`:empty('No corrections recorded','A submitted correction and its processing result will appear here.')}</section>`;}
async function correctionForm(){
 if(state.role!=='SELLER')throw Error('Seller access required.');if(correctionBusy())throw Error('A correction is already being processed. Refresh to check its result.');const r=await live.application(state.id),p=r.businessProfile;if(r.status!=='ACTION_REQUIRED')throw Error('The application status is still synchronizing. Use Refresh at the top and try again.');
 modal('Correct application',`<p class="modal-intro">Only an application requiring action before lender dispatch can be corrected. These changes affect this application, and keep its previous revision. Marketplace source records are managed separately. Financial-data permission must be granted for the new revision.</p><form><div class="form-grid">${amountField('Amount requested in INR','requestedAmount',r.requestedAmount,'required min="0.01" max="999999999.99" step="0.01"')}<div class="field"><label for="loanPurpose">Loan purpose</label><select id="loanPurpose" name="loanPurpose" required disabled>${['WORKING_CAPITAL','PURCHASE_INVENTORY','BUSINESS_EXPANSION'].map(v=>`<option value="${v}" ${r.loanPurpose===v?'selected':''}>${e(human(v))}</option>`).join('')}</select></div>${field('Seller display name','displayName',p.displayName,'text','required maxlength="100"')}${field('Business name','businessName',p.businessName,'text','required maxlength="200"')}${field('Business start date','businessStartDate',p.businessStartDate,'date',`required max="${new Date().toISOString().slice(0,10)}"`)}</div>${phase0Fields(p.phase0||{})}<div id="form-error" class="error-inline" role="alert"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="button primary">Submit correction</button></div></form>`,async form=>{const fd=new FormData(form),data={expectedApplicationRevision:r.applicationRevision,expectedVersion:r.version,requestedAmount:Number(fd.get('requestedAmount')).toFixed(2),loanPurpose:r.loanPurpose,businessProfile:{displayName:String(fd.get('displayName')).trim(),businessName:String(fd.get('businessName')).trim(),businessStartDate:String(fd.get('businessStartDate')),phase0:phase0Input(form)}};await live.request('application',`/api/v1/applications/${state.id}/corrections`,data);closeModal();go(`application/${state.id}/corrections`);toast('Correction queued. Follow its status here, then review permissions for the new revision.');});
}

function lendersView(){return heading('Lenders / banks','Create lender organizations and their officer login.',button('Create lender','create-lender','primary'))+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Lender</th><th>Code / type</th><th>Officer login</th><th>Status</th></tr></thead><tbody>${state.lenders.map(r=>`<tr><td>${e(r.name)}</td><td>${e(r.code)} / ${e(r.type)}</td><td>${e(r.username)}<br><span class="muted small">${e(r.emailAddress)}</span></td><td>${badge(r.status)}</td></tr>`).join('')||'<tr><td colspan="4">No lenders configured.</td></tr>'}</tbody></table></div><div class="card-body"><p>All lender officers sign in at <a href="http://localhost:5176">localhost:5176</a>. Each sees only their own lender records. New lenders use the shared local bank simulator and start with an inactive product. The lender must review and activate its own rules before receiving applications.</p></div></section>`;}
function lenderForm(){
 if(state.role!=='ADMIN')throw Error('Administrator access required.');
 modal('Create lender',`<p class="modal-intro">Create a bank or NBFC and its officer credentials. Its product is added at the last routing position with inactive rules.</p><form><div class="form-grid">${field('Lender / bank name','name','','text','required maxlength="150"')}${field('Unique lender code','code','','text','required pattern="[a-z][a-z0-9-]{2,19}" minlength="3" maxlength="20" placeholder="example-bank"')}<div class="field"><label for="type">Lender type</label><select id="type" name="type"><option value="BANK">Bank</option><option value="NBFC">NBFC</option></select></div>${field('Officer username','username','','text','required minlength="3" maxlength="100" pattern="[A-Za-z0-9._-]+" autocomplete="off"')}${field('Officer email','emailAddress','','email','required maxlength="255"')}${field('Initial password','password','','password','required minlength="12" maxlength="72" autocomplete="new-password"')}${field('Confirm password','confirmPassword','','password','required minlength="12" maxlength="72" autocomplete="new-password"')}${field('Reason for creating lender','reason','','text','required maxlength="450"')}</div><div id="form-error" class="error-inline" role="alert"></div><div class="form-actions">${button('Cancel','close')}<button class="button primary" type="submit">Create lender</button></div></form>`,async form=>{const data=Object.fromEntries(new FormData(form));if(data.password!==data.confirmPassword)throw Error('Passwords do not match.');delete data.confirmPassword;await live.request('auth','/api/v1/admin/lenders',data,'POST');form.reset();closeModal();await load();toast('Lender created. The officer can sign in at localhost:5176 and configure their rules.');});
}
function marketplacesView(){return heading('Marketplaces','Manage marketplace access and registration.',button('Create marketplace','create-marketplace','primary'))+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Marketplace</th><th>Prefix</th><th>Login</th><th>Status</th><th>Sellers</th><th>Actions</th></tr></thead><tbody>${state.marketplaces.map(r=>`<tr><td>${e(r.name)}</td><td>${e(r.referencePrefix)}</td><td>${e(r.username)}<br><span class="muted small">${e(r.emailAddress)}</span></td><td>${badge(r.status)}</td><td>${e(r.sellerCount)}</td><td><div class="row-actions">${button('View','view-marketplace','small',`data-id="${e(r.marketplaceId)}"`)}${button('Edit','edit-marketplace','small',`data-id="${e(r.marketplaceId)}"`)}${Number(r.sellerCount)===0?button('Delete unused','delete-marketplace','danger small',`data-id="${e(r.marketplaceId)}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="6">No marketplaces have been created.</td></tr>'}</tbody></table></div><div class="card-body"><p class="muted small">Inactive marketplaces stop accepting new registrations and loan requests. Existing sellers, loans and audit records remain accessible.</p></div>${pagination()}</section>`;}
async function marketplaceForm(id){
 if(state.role!=='ADMIN')throw Error('Administrator access required.');
 const r=id?await live.request('auth',`/api/v1/admin/marketplaces/${id}`):{};
 const inputs=field('Marketplace name','name',r.name||'','text','required maxlength="150"')+(!id?field('Seller reference prefix (2-8 letters or digits)','referencePrefix','','text','required pattern="[A-Za-z][A-Za-z0-9]{1,7}" maxlength="8"')+field('Marketplace login username','username','','text','required pattern="[A-Za-z0-9._-]+" minlength="3" maxlength="100" autocomplete="off"'):'')+field('Operator email','emailAddress',r.emailAddress||'','email','required maxlength="255"')+(!id?field('Login password (12-72 characters)','password','','password','required minlength="12" maxlength="72" autocomplete="new-password"')+field('Confirm password','confirmPassword','','password','required minlength="12" maxlength="72" autocomplete="new-password"'):`<div class="field"><label for="status">Intake status</label><select id="status" name="status"><option value="ACTIVE" ${r.status==='ACTIVE'?'selected':''}>Active - accept new sellers and loan requests</option><option value="INACTIVE" ${r.status==='INACTIVE'?'selected':''}>Inactive - pause new sellers and loan requests</option></select></div><p class="muted small">Login username and seller prefix stay fixed to preserve existing references.</p>`);
 modal(id?'Edit marketplace':'Create marketplace',`<p class="modal-intro">${id?'Update the name, operator email or intake status.':'Create the marketplace and its operator login. Seller references and automatic application submission are configured together.'}</p><form><div class="form-grid">${inputs}</div><div id="form-error" class="error-inline" role="alert"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="button primary">${id?'Save marketplace':'Create marketplace'}</button></div></form>`,async form=>{const data=Object.fromEntries(new FormData(form));if(!id){if(data.password!==data.confirmPassword)throw Error('Passwords do not match.');delete data.confirmPassword;}else data.expectedVersion=r.version;await live.request('auth',`/api/v1/admin/marketplaces${id?'/'+id:''}`,data,id?'PUT':'POST');form.reset();closeModal();await load();toast(id?'Marketplace saved.':'Marketplace created. The operator can sign in at the marketplace portal.');});
}
async function viewMarketplace(id){if(state.role!=='ADMIN')throw Error('Administrator access required.');const r=await live.request('auth',`/api/v1/admin/marketplaces/${id}`);modal('Marketplace details',`<dl class="data-grid">${item('Marketplace',r.name)}${item('Status',human(r.status))}${item('Login username',r.username)}${item('Operator email',r.emailAddress)}${item('Seller prefix',r.referencePrefix)}${item('Registered sellers',r.sellerCount)}${item('Marketplace ID',r.marketplaceId,true)}</dl><div class="form-actions">${button('Close','close')}</div>`);}
